def transform(grid):
    h, w = len(grid), len(grid[0])
    # A full separator divides two panels. Overlay their foreground masks;
    # every aligned nonzero/nonzero pair becomes 2.
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c+1:] for row in grid]
            return [[2 if a != 0 and b != 0 else 0
                     for a, b in zip(ra, rb)] for ra, rb in zip(left, right)]
    for r in range(h):
        if len(set(grid[r])) == 1:
            top, bottom = grid[:r], grid[r+1:]
            return [[2 if a != 0 and b != 0 else 0
                     for a, b in zip(ra, rb)] for ra, rb in zip(top, bottom)]
    return grid
